# ==============================================================================
# 11. High-confidence candidate shortlist
# ==============================================================================

HIGH_CONF_CLASSES <- c(
  "Strong_Tx_gain",
  "Strong_Tx_loss",
  "Replicate_consistent_Tx_up",
  "Replicate_consistent_Tx_down"
)

candidate_shortlist <- lr_refined %>%
  filter(
    total_support_replicates >=
      2,
    pairwise_direction_consistency >=
      0.75,
    priority_pathway |
      confidence_class %in%
        HIGH_CONF_CLASSES
  ) %>%
  mutate(
    mechanistic_focus = case_when(

      source ==
        "ECM-associated inflammatory-Mphi" ~
        "Primary_ECM-inflammatory_to_HSC",

      source %in%
        c(
          "Anti-inflammatory-Mphi",
          "Repair/Resolution-Mphi"
        ) ~
        "Resolution_axis_to_HSC",

      TRUE ~
        "Other_Mphi_to_HSC"
    )
  ) %>%
  arrange(
    desc(
      confidence_class %in%
        HIGH_CONF_CLASSES
    ),
    desc(
      priority_pathway
    ),
    desc(
      refinement_rank_score
    )
  )

write.csv(
  candidate_shortlist,
