# ==============================================================================
# 12. Figure 1:
#     refined pathway relative-delta heatmap
#
# Bounded relative delta avoids the giant values caused by zero denominators.
# ==============================================================================

heat_df <- priority_pathway_refined %>%
  filter(
    total_support_replicates >=
      1
  ) %>%
  mutate(
    sender_receiver =
      paste0(
        source,
        " -> ",
        target
      )
  )

pathway_order <- heat_df %>%
  group_by(
    pathway_name
  ) %>%
  summarise(
    max_rank =
      max(
        refinement_rank_score,
        na.rm = TRUE
      ),
    .groups = "drop"
  ) %>%
  arrange(
    desc(
      max_rank
    )
  ) %>%
  slice_head(
    n = 30
  ) %>%
  pull(
    pathway_name
  )

heat_df <- heat_df %>%
  filter(
    pathway_name %in%
      pathway_order
  ) %>%
  mutate(
    pathway_name =
      factor(
        pathway_name,
        levels =
          rev(
            pathway_order
          )
      )
  )

if (
  nrow(
    heat_df
  )
) {

  p1 <- ggplot(
    heat_df,
    aes(
      x =
        sender_receiver,
      y =
        pathway_name,
      fill =
        relative_delta_supported
    )
  ) +
    geom_tile(
      linewidth = 0.25
    ) +
    scale_fill_gradient2(
      low = "#0033FF",
      mid = "#FFFFFF",
      high = "#FF1A1A",
      midpoint = 0,
      limits = c(
        -1,
        1
      )
    ) +
    labs(
      title =
        "Refined Mphi -> HSC pathway change",
      subtitle =
        "Relative delta of p<0.05-supported communication; red = Tx higher, blue = Tx lower",
      x = NULL,
      y = NULL,
      fill =
        "Relative delta"
    ) +
    theme_classic(
      base_size = 7
    ) +
    theme(
      axis.text.x =
        element_text(
          angle = 60,
          hjust = 1
        ),
      plot.title =
        element_text(
          face = "bold",
          hjust = 0.5
        )
    )

  save_pdf(
    p1,
    file.path(
      FIG_OUT,
      "01_refined_priority_pathway_relative_delta_heatmap_v6.2.2.pdf"
    ),
    18,
    10
  )
}


